export declare const LEAFLET_EXAMPLES = "# Leaflet Examples Collection\n\n## Quick Start\nhttps://leafletjs.com/examples/quick-start/\n\nBasic map setup with markers and popups.\n\n```javascript\nvar map = L.map('map').setView([51.505, -0.09], 13);\nL.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {\n  attribution: '\u00A9 OpenStreetMap'\n}).addTo(map);\n\nvar marker = L.marker([51.5, -0.09]).addTo(map)\n  .bindPopup('A popup!').openPopup();\n```\n\n---\n\n## Mobile-Friendly Maps\nhttps://leafletjs.com/examples/mobile/\n\nFullscreen map with geolocation for mobile devices.\n\n```javascript\nvar map = L.map('map', {\n  center: [51.505, -0.09],\n  zoom: 13,\n  minZoom: 2,\n  maxZoom: 18\n});\n\n// Get user location\nmap.locate({setView: true, maxZoom: 16});\n\nmap.on('locationfound', function(e) {\n  var radius = e.accuracy / 2;\n  L.marker(e.latlng).addTo(map)\n    .bindPopup(\"You are within \" + radius + \" meters\");\n  L.circle(e.latlng, radius).addTo(map);\n});\n\nmap.on('locationerror', function(e) {\n  alert(e.message);\n});\n```\n\n---\n\n## Custom Marker Icons\nhttps://leafletjs.com/examples/custom-icons/\n\nCreate and use custom icons for markers.\n\n```javascript\nvar greenIcon = L.icon({\n  iconUrl: 'leaf-green.png',\n  shadowUrl: 'leaf-shadow.png',\n  iconSize: [38, 95],\n  shadowSize: [50, 64],\n  iconAnchor: [22, 94],\n  shadowAnchor: [4, 62],\n  popupAnchor: [-3, -76]\n});\n\nL.marker([51.5, -0.09], {icon: greenIcon}).addTo(map);\n\n// Icon with different states\nvar LeafIcon = L.Icon.extend({\n  options: {\n    shadowUrl: 'leaf-shadow.png',\n    iconSize: [38, 95],\n    shadowSize: [50, 64],\n    iconAnchor: [22, 94],\n    shadowAnchor: [4, 62],\n    popupAnchor: [-3, -76]\n  }\n});\n\nvar greenIcon = new LeafIcon({iconUrl: 'leaf-green.png'});\nvar redIcon = new LeafIcon({iconUrl: 'leaf-red.png'});\nvar orangeIcon = new LeafIcon({iconUrl: 'leaf-orange.png'});\n```\n\n---\n\n## GeoJSON\nhttps://leafletjs.com/examples/geojson/\n\nDisplay and interact with GeoJSON data.\n\n```javascript\nvar geojsonFeature = {\n  \"type\": \"Feature\",\n  \"properties\": {\n    \"name\": \"Coors Field\",\n    \"amenity\": \"Baseball Stadium\",\n    \"popupContent\": \"Home of the Rockies!\"\n  },\n  \"geometry\": {\n    \"type\": \"Point\",\n    \"coordinates\": [-104.99404, 39.75621]\n  }\n};\n\nL.geoJSON(geojsonFeature, {\n  onEachFeature: function(feature, layer) {\n    if (feature.properties && feature.properties.popupContent) {\n      layer.bindPopup(feature.properties.popupContent);\n    }\n  }\n}).addTo(map);\n\n// Custom styling\nL.geoJSON(geojsonData, {\n  style: function(feature) {\n    return {color: feature.properties.color};\n  },\n  pointToLayer: function(feature, latlng) {\n    return L.circleMarker(latlng, {\n      radius: 8,\n      fillColor: \"#ff7800\",\n      weight: 1,\n      opacity: 1,\n      fillOpacity: 0.8\n    });\n  }\n}).addTo(map);\n```\n\n---\n\n## Interactive Choropleth Map\nhttps://leafletjs.com/examples/choropleth/\n\nData visualization with color-coded regions.\n\n```javascript\n// Define color scale\nfunction getColor(d) {\n  return d > 1000 ? '#800026' :\n         d > 500  ? '#BD0026' :\n         d > 200  ? '#E31A1C' :\n         d > 100  ? '#FC4E2A' :\n         d > 50   ? '#FD8D3C' :\n         d > 20   ? '#FEB24C' :\n         d > 10   ? '#FED976' :\n                    '#FFEDA0';\n}\n\n// Style function\nfunction style(feature) {\n  return {\n    fillColor: getColor(feature.properties.density),\n    weight: 2,\n    opacity: 1,\n    color: 'white',\n    dashArray: '3',\n    fillOpacity: 0.7\n  };\n}\n\n// Interaction\nfunction highlightFeature(e) {\n  var layer = e.target;\n  layer.setStyle({\n    weight: 5,\n    color: '#666',\n    dashArray: '',\n    fillOpacity: 0.7\n  });\n  info.update(layer.feature.properties);\n}\n\nfunction resetHighlight(e) {\n  geojson.resetStyle(e.target);\n  info.update();\n}\n\nfunction onEachFeature(feature, layer) {\n  layer.on({\n    mouseover: highlightFeature,\n    mouseout: resetHighlight,\n    click: zoomToFeature\n  });\n}\n\nvar geojson = L.geoJSON(statesData, {\n  style: style,\n  onEachFeature: onEachFeature\n}).addTo(map);\n```\n\n---\n\n## Layer Groups and Layers Control\nhttps://leafletjs.com/examples/layers-control/\n\nOrganize layers and add control to switch between them.\n\n```javascript\n// Base layers\nvar osm = L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png');\nvar satellite = L.tileLayer('https://server.arcgisonline.com/...');\n\n// Overlay layers\nvar cities = L.layerGroup([\n  L.marker([39.61, -105.02]).bindPopup('Denver'),\n  L.marker([39.74, -104.99]).bindPopup('Boulder')\n]);\n\nvar markers = L.layerGroup([\n  L.marker([51.5, -0.09]),\n  L.marker([51.495, -0.083])\n]);\n\n// Create map with default layers\nvar map = L.map('map', {\n  center: [39.73, -104.99],\n  zoom: 10,\n  layers: [osm, cities]\n});\n\n// Add layers control\nvar baseMaps = {\n  \"OpenStreetMap\": osm,\n  \"Satellite\": satellite\n};\n\nvar overlayMaps = {\n  \"Cities\": cities,\n  \"Markers\": markers\n};\n\nL.control.layers(baseMaps, overlayMaps).addTo(map);\n```\n\n---\n\n## Working with Popups\nhttps://leafletjs.com/examples/custom-icons/\n\nDifferent ways to use popups.\n\n```javascript\n// Standalone popup\nvar popup = L.popup()\n  .setLatLng([51.513, -0.09])\n  .setContent(\"I am a standalone popup.\")\n  .openOn(map);\n\n// Popup with custom options\nmarker.bindPopup(\"Popup content\", {\n  maxWidth: 250,\n  className: 'custom-popup'\n});\n\n// Popup with HTML\nvar customPopup = `\n  <div class=\"custom-popup\">\n    <h3>Title</h3>\n    <p>Description here</p>\n    <button onclick=\"alert('Clicked!')\">Click</button>\n  </div>\n`;\n\nmarker.bindPopup(customPopup, {\n  maxWidth: 300,\n  closeButton: false\n});\n```\n\n---\n\n## Using WMS and TMS Services\nhttps://leafletjs.com/examples/wms/\n\nIntegrate with professional GIS services.\n\n```javascript\n// WMS layer\nvar nexrad = L.tileLayer.wms(\"http://mesonet.agron.iastate.edu/cgi-bin/wms/nexrad/n0r.cgi\", {\n  layers: 'nexrad-n0r-900913',\n  format: 'image/png',\n  transparent: true,\n  attribution: \"Weather data \u00A9 NOAA\"\n});\n\n// Single tile WMS\nvar wmsLayer = L.tileLayer.wms('http://ows.mundialis.de/services/service?', {\n  layers: 'TOPO-WMS'\n});\n\nmap.addLayer(nexrad);\n```\n\n---\n\n## Non-geographical Maps\nhttps://leafletjs.com/examples/crs-simple/\n\nUse Leaflet for non-geographical images (game maps, floor plans).\n\n```javascript\n// Simple CRS for pixel coordinates\nvar map = L.map('map', {\n  crs: L.CRS.Simple,\n  minZoom: -5,\n  maxZoom: 4\n});\n\n// Image overlay\nvar bounds = [[0,0], [1000, 1000]];\nvar image = L.imageOverlay('uqm_map_full.png', bounds).addTo(map);\n\nmap.fitBounds(bounds);\n\n// Add markers with pixel coordinates\nvar marker = L.marker([750, 500]).addTo(map)\n  .bindPopup('Coordinates: 750, 500');\n```\n\n---\n\n## Map Panes\nhttps://leafletjs.com/examples/map-panes/\n\nControl layer ordering with custom panes.\n\n```javascript\n// Create custom pane\nmap.createPane('labels');\nmap.getPane('labels').style.zIndex = 650;\nmap.getPane('labels').style.pointerEvents = 'none';\n\n// Add layers to panes\nvar positron = L.tileLayer('https://{s}.basemaps.cartocdn.com/light_nolabels/{z}/{x}/{y}.png').addTo(map);\n\nvar positronLabels = L.tileLayer('https://{s}.basemaps.cartocdn.com/light_only_labels/{z}/{x}/{y}.png', {\n  pane: 'labels'\n}).addTo(map);\n```\n\n---\n\n## Video Overlay\nhttps://leafletjs.com/examples/video-overlay/\n\nAdd video as a map overlay.\n\n```javascript\nvar videoUrls = [\n  'https://example.com/video.webm',\n  'https://example.com/video.mp4'\n];\n\nvar videoBounds = [\n  [32, -130],\n  [13, -100]\n];\n\nvar videoOverlay = L.videoOverlay(videoUrls, videoBounds, {\n  opacity: 0.8,\n  autoplay: true,\n  loop: true\n}).addTo(map);\n```\n\n---\n\n## Zoom Levels\nhttps://leafletjs.com/examples/zoom-levels/\n\nUnderstanding and controlling zoom levels.\n\n```javascript\n// Zoom to bounds\nvar bounds = [\n  [40.712, -74.227],\n  [40.774, -74.125]\n];\nmap.fitBounds(bounds);\n\n// Smooth animated zoom\nmap.flyTo([51.505, -0.09], 13, {\n  duration: 2\n});\n\n// Zoom with animation\nmap.setZoom(15, {\n  animate: true,\n  duration: 1\n});\n\n// Restrict zoom levels\nvar map = L.map('map', {\n  minZoom: 10,\n  maxZoom: 16,\n  maxBounds: bounds,\n  maxBoundsViscosity: 1.0\n});\n```\n\n---\n\n## Extending Leaflet\nhttps://leafletjs.com/examples/extending/\n\nCreate custom classes and controls.\n\n```javascript\n// Custom control\nL.Control.Watermark = L.Control.extend({\n  onAdd: function(map) {\n    var img = L.DomUtil.create('img');\n    img.src = 'logo.png';\n    img.style.width = '200px';\n    return img;\n  }\n});\n\nL.control.watermark = function(opts) {\n  return new L.Control.Watermark(opts);\n}\n\nL.control.watermark({ position: 'bottomleft' }).addTo(map);\n\n// Custom layer\nL.GridLayer.DebugCoords = L.GridLayer.extend({\n  createTile: function (coords) {\n    var tile = document.createElement('div');\n    tile.innerHTML = [coords.x, coords.y, coords.z].join(', ');\n    tile.style.outline = '1px solid red';\n    return tile;\n  }\n});\n\nL.gridLayer.debugCoords = function(opts) {\n  return new L.GridLayer.DebugCoords(opts);\n};\n\nmap.addLayer(L.gridLayer.debugCoords());\n```\n\n---\n\n## Accessibility\nhttps://leafletjs.com/examples/accessibility/\n\nMake maps accessible.\n\n```javascript\n// Keyboard navigation\nvar map = L.map('map', {\n  keyboard: true,\n  keyboardPanDelta: 80\n});\n\n// ARIA labels\nvar marker = L.marker([51.5, -0.09], {\n  keyboard: true,\n  title: 'London',\n  alt: 'Marker showing London location'\n}).addTo(map);\n\n// Focus control\nmap.on('focus', function() {\n  console.log('Map focused');\n});\n```\n\n---\n\n## Performance Tips\n\n### Marker Clustering\nUse Leaflet.markercluster for many markers:\n```javascript\nvar markers = L.markerClusterGroup();\nfor (var i = 0; i < 1000; i++) {\n  markers.addLayer(L.marker(getRandomLatLng()));\n}\nmap.addLayer(markers);\n```\n\n### Canvas Renderer\nUse Canvas for better performance with many vectors:\n```javascript\nvar map = L.map('map', {\n  renderer: L.canvas()\n});\n```\n\n### Simplify Geometries\nReduce points for better performance:\n```javascript\nvar polyline = L.polyline(coordinates, {\n  smoothFactor: 3.0\n}).addTo(map);\n```\n\n---\n\nFor more examples, visit: https://leafletjs.com/examples.html\n";
